///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.libRoundPanel.PanelToGroupBox(panel_1);
        $c.cm.PanelToGroupBox(panel_2);
        $c.libRoundPanel.PanelToGroupBox(panel_3);
        await scwin.getNextDay();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF41010.onpageload" });
    }
};

/**
 * @method
