/**
 * @method
 * @name inf_find_OnClick
 * @description inf_find 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.inf_find_OnClick = function() {
    try {
        const filenm = dts_fileList.getCellData(dts_fileList.getRowPosition(), "filename");
        if (com_schdl_id === "") {
            dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.getValue());
            file_name.setValue(inf_find.getValue());
        } else {
            dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.getValue());
            dts_fileList.setCellData(dts_fileList.getRowPosition(), "ATTACH_SEQ", dts_fileList.getRowPosition());
            file_name.setValue(inf_find.getValue());
        }
        if (inf_find.getValue() === "") {
            file_name.setValue(filenm);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF41010.inf_find_OnClick" });
    }
};

/**
 * @method
 * @name btn_lineadd_onclick
 * @description 「파일추가」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_lineadd_onclick = async function() {
    try {
        if (dts_fileList.getRowCount() >= 5) {
            await $c.win.alert("더이상 추가하실 수 없습니다.");
            return;
        }
        dts_fileList.insertRow();
        inf_find.open();
        if (inf_find.getValue() !== "") {
            const temp = (inf_find.getValue()).split("\\");
            if (!await scwin.checkMaxLength3(temp[temp.length - 1], 80, "파일명")) {
                dts_fileList.removeRow(dts_fileList.getRowPosition());
            } else {
                dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.getValue());
                file_name.setValue(inf_find.getValue());
                scwin.gLastJob = "저장";
                if (await scwin.validDateCheck() && confirm(scwin.gLastJob + ' 하시겠습니까?')) {
                    scwin.saveAttachFile();
                } else {
                    dts_fileList.removeRow(dts_fileList.getRowPosition());
                }
            }
        } else {
            dts_fileList.removeRow(dts_fileList.getRowPosition());
        }
        if (!scwin.canUploadFile()) {
            await $c.win.alert('30MB 이하의 파일만 첨부 가능합니다.');
            dts_fileList.removeRow(dts_fileList.getRowPosition());
            return;
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF41010.btn_lineadd_onclick" });
    }
};

/**
 * @method
 * @name btn_linedelete_onclick
 * @description 「파일삭제」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_linedelete_onclick = async function() {
    try {
        if (dts_fileList.getRowCount() === 0) {
            return;
        }
        scwin.gLastJob = "삭제";
        if (await scwin.validDateCheck() && confirm(scwin.gLastJob + ' 하시겠습니까?')) {
            dts_fileList.removeRow(dts_fileList.getRowPosition());
            scwin.saveAttachFile();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF41010.btn_linedelete_onclick" });
    }
};

/**
 * @method
 * @name grd_fileList_OnDblClick
 * @description grd_fileList 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_fileList_OnDblClick = function(row, colid) {
    try {
        if (row === 0) return;
        if (dts_fileList.getRowStatus(dts_fileList.getRowPosition()) === 0) {
            scwin.filedown(dts_fileList.getCellData(row, "ATTACH_FILE_ID"), dts_fileList.getCellData(row, "ATTACH_SEQ"));
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF41010.grd_fileList_OnDblClick" });
    }
};

