/**
 * @method
 * @name initProcsStat
 * @description init Procs Stat 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.initProcsStat = async function() {
    if (!await scwin.validDateTodayCheck()) {
        return;
    }
    const aProcsNm = new Array();
    aProcsNm[1] = "미처리";
    aProcsNm[2] = "1차 검토";
    aProcsNm[3] = "2차 검토";
    aProcsNm[9] = "승인";

    // alert(aProcsNm[gStatTp]);

    let vAnswer = confirm(aProcsNm[scwin.gStatTp] + ' 취소하시겠습니까?');
    if (vAnswer === true) {
        dts_UpdateProcs.setCellData(1, "CONFRM_DD", scwin.gSearchDay);
        dts_UpdateProcs.setCellData(1, "MSG4", scwin.getTime());
        scwin.gLastJob = "취소";
        trs_UpdateProcs.KeyName = "toinb_dataid4";
        const sbmOptions = {
            id : "sbm_trs_UpdateProcs",
            action : "/PersonOnDuty.do",
            ref : "dts_UpdateProcs",
            target : "trs_UpdateProcs=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

/**
 * @method
 * @name saveProcsStat
 * @description save Procs Stat 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.saveProcsStat = async function() {
    if (!await scwin.validDateTodayCheck()) {
        return;
    }
    let sProcsNm = scwin.gStatTp === 3 ? '승인' : scwin.gStatTp + '차 검토';
    const sEmpNm = dts_Transtr.getCellData(1, "EMP_NM" + scwin.gStatTp);
    const sProcsDdtm = dts_Transtr.getCellData(1, "PROCS_DDTM" + scwin.gStatTp);
    if (sProcsDdtm.length > 0) {
        await $c.win.alert(sEmpNm + "님에 의해 처리되었습니다. (" + sProcsDdtm + ")");
        scwin.readProcsStat();
        return;
    }
    dts_UpdateProcs.setCellData(1, "CONFRM_DD", scwin.gSearchDay);
    dts_UpdateProcs.setCellData(1, "DUTY_DIARY_PROCS_STAT_CD", scwin.gStatCd);
    dts_UpdateProcs.setCellData(1, "MSG4", scwin.getTime());
    scwin.gLastJob = sProcsNm;
    trs_UpdateProcs.KeyName = "toinb_dataid4";
    const sbmOptions = {
        id : "sbm_trs_UpdateProcs",
        action : "/PersonOnDuty.do",
        ref : "dts_UpdateProcs",
        target : "trs_UpdateProcs=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

