/**
 * @method
 * @name delete
 * @description delete 처리
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.delete = async function(row, colid) {
    const res = window.confirm("삭제하시겠습니까?");
    if (await scwin.validDateCheck() && res) {
        scwin.gLastJob = "삭제";
        /*
        var url = "/PersonOnDuty.do?method=deleteDutyDiaryMktactDtl";
        	url += "&CONFRM_DD=" + dts_Diary.NameString(row, "CONFRM_DD");
        	url += "&DIARY_SEQ=" + dts_Diary.NameString(row, "DIARY_SEQ");
        	url += "&TRANSTR_EMP_NO=" + js_emp_no;
        	url += "&SCREN_ID=" + vScrenID;
        	url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;

        dts_Diary.DataID = encodeURI(url);
        dts_Diary.Reset();
         */
        const sCONFRM_DD = dts_Diary.getCellData(row, "CONFRM_DD");
        const sDIARY_SEQ = dts_Diary.getCellData(row, "DIARY_SEQ");
