/**
 * @method
 * @name getToday
 * @description get Today 처리
 * @returns {void}
 * @hidden N
 */
scwin.getToday = function() {
    const date_now = new Date();
    const y = date_now.getFullYear().toString();
    let m = (date_now.getMonth() + 1).toString().length === 1 ? "0" + (date_now.getMonth() + 1).toString() : (date_now.getMonth() + 1).toString();
    const d = date_now.getDate().toString().length === 1 ? "0" + date_now.getDate().toString() : date_now.getDate().toString();
    let h = date_now.getHours();
    if (h >= 13) {
        // 13시 이후 다음날로 간주
        return scwin.gNextday;
    }
    return '' + y + m + d;
};

/**
 * @method
 * @name getTime
 * @description get Time 처리
 * @returns {void}
 * @hidden N
 */
scwin.getTime = function() {
    const date = new Date();
    let h = date.getHours().toString();
    let m = date.getMinutes().toString().length === 1 ? "0" + date.getMinutes().toString() : date.getMinutes().toString();
    const s = date.getSeconds().toString().length === 1 ? "0" + date.getSeconds().toString() : date.getSeconds().toString();
    return '' + h + m + s;
};

