/**
 * @method
 * @name validConfrmCheck
 * @description valid Confrm Check 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.validConfrmCheck = async function() {
    let err_row = 0;
    let err_col = 0;
    for (let i = 1; i <= dts_Confrm.getRowCount(); i++) {
        for (let j = 1; j <= 2; j++) {
            if (dts_Confrm.getCellData(i, "CONFRM_SEQ" + j) !== '') {
                if (dts_Confrm.getCellData(i, "DUTY_CONFRM_YN" + j) !== 'Y') {
                    err_row = i;
                    err_col = j;
                    i = dts_Confrm.getRowCount() + 1;
                    j = 3;
                }
            }
        }
    }
    if (err_row > 0) {
        dts_Confrm.setRowPosition(err_row, 0);
        await $c.win.alert("당번 확인이 완료되지 않았습니다.\n[당번 확인사항]을 확인해 주세요.");
        grd_List2.SetColumn("DUTY_CONFRM_YN" + err_col);
        grd_List2.focus();
        return false;
    }
    return true;
};

/**
 * @method
 * @name validCheck
 * @description valid Check 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.validCheck = async function() {
    if (edt_Date.getValue() === "") {
        await $c.win.alert("[반영일]을 입력하세요.");
        edt_Date.focus();
        return false;
    }
    if (cmb_DIARY_TP_CD.getValue() === "") {
        await $c.win.alert("[구분]을 입력하세요.");
        cmb_DIARY_TP_CD.focus();
        return false;
    }
    if (txb_isur_cd.getValue() === "") {
        await $c.win.alert("[종목코드]를 입력하세요.");
        txb_isur_cd.focus();
        return false;
    }
    if (txb_CONTN.getValue() === "") {
        await $c.win.alert("[내용]을 입력하세요.");
        txb_CONTN.focus();
        return false;
    }
    /*
    if (getObjectValue(txb_REF_CONTN) == "") {
    	alert("[참고사항]을 입력하세요.");
    	txb_REF_CONTN.focus();
    	return false;
    }
     */
    if (cmb_DEP_CD.getValue() === "") {
        await $c.win.alert("[팀]을 입력하세요.");
        cmb_DEP_CD.focus();
        return false;
    }
    if (cmb_EMP_NO.getValue() === "") {
        await $c.win.alert("[조치자]를 입력하세요.");
        cmb_EMP_NO.focus();
        return false;
    }
    if (!await scwin.checkMaxLength1(txb_CONTN, 200, "내용")) {
        txb_CONTN.setValue("");
        txb_CONTN.focus();
        return false;
    }
    if (!await scwin.checkMaxLength1(txb_REF_CONTN, 200, "참고사항")) {
        txb_REF_CONTN.setValue("");
        txb_CONTN.focus();
        return false;
    }
    return true;
};

