/**
 * @method
 * @name setModifyAuth
 * @description 수정권한 설정
 * @returns {void}
 * @hidden N
 */
scwin.setModifyAuth = function() {
    // alert(getObjectValue(edt_Date) + "\n" + fn_getToday());
    // 오늘날짜  버튼 비활성화
    if (Number(edt_Date.getValue()) < Number(scwin.getToday())) {
        scwin.setDisable();
    } else if (Number(edt_Date.getValue()) > Number(scwin.getToday())) {
        // 1,2차 검토 && 승인, 취소
        scwin.setDisable1();
        scwin.setDisable11();

        // 시장조치
        scwin.setEnable2();

        // 당번 확인사항 && 파일첨부
        if (scwin.gDutyYn === 'Y' || scwin.gDutyChrg === 'Y') {
            scwin.setEnable3();
            scwin.setEnable4();
        }
    } else {
        // alert(gDutyYn + "\n" + gDutyChrg + "\n" + gStatTp);
        // 1,2차 검토
        if ((scwin.gDutyYn !== 'Y' || scwin.gStatTp > 2) && (scwin.gDutyChrg !== 'Y' || scwin.gStatTp !== 3)) {
            // 당번
            scwin.setDisable1();
        }

        // 승인
        // if(gDutyChrg != 'Y' || gStatTp != 3) {        //당번팀장
        //    fn_SetDisable1();
        // }

        // 취소
        if (scwin.gDutyYn !== 'Y' && scwin.gDutyChrg !== 'Y') {
            scwin.setDisable11();
        }

        // 시장조치
        if (scwin.gStatTp > 2) {
            // 2차검토 후 시장조치 입력불가
            scwin.setDisable2();
        } else {
            scwin.setEnable2();
        }

        // 당번 확인사항
        if ((scwin.gDutyYn === 'Y' || scwin.gDutyChrg === 'Y') && scwin.gStatTp === 1) {
            scwin.setEnable3();
        } else {
            scwin.setDisable3();
        }

        // 파일첨부
        if ((scwin.gDutyYn === 'Y' || scwin.gDutyChrg === 'Y') && scwin.gStatTp !== 9) {
            scwin.setEnable4();
        } else {
            scwin.setDisable4();
        }
    }
};

/**
 * @method
 * @name btnPrint
 * @description btn Print 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btnPrint = async function() {
    if (scwin.gStatTp !== 9) {
        await $c.win.alert("승인 처리가 되지 않았습니다.");
        return;
    }
    scwin.printPdf();
};

/**
 * @method
 * @name printPdf
 * @description print Pdf 처리
 * @returns {void}
 * @hidden N
 */
scwin.printPdf = function() {
    const pdf_rptname = "RLDSTF41010";
    const confrm_dd = scwin.gSearchDay.substring(0, 4) + "-" + scwin.gSearchDay.substring(4, 6) + "-" + scwin.gSearchDay.substring(6, 8);
    let tbl1 = "";
    for (let i = 1; i <= dts_Diary.getRowCount(); i++) {
        tbl1 += "<tr>";
        tbl1 += "		<td>" + dts_Diary.getCellData(i, "DEP_NM") + "</td>";
        tbl1 += "		<td>" + dts_Diary.getCellData(i, "EMP_NM") + "</td>";
        tbl1 += "		<td>" + dts_Diary.getCellData(i, "COM_ABBRV") + "</td>";
        tbl1 += "		<td>" + dts_Diary.getCellData(i, "DUTY_DIARY_MKTACT_TP_NM") + "</td>";
        tbl1 += "		<td style='text-align: left;'>" + dts_Diary.getCellData(i, "DUTY_DIARY_MKTACT_CONTN") + "</td>";
        tbl1 += "		<td style='text-align: left;'>" + dts_Diary.getCellData(i, "DUTY_DIARY_MKTACT_REF_CONTN") + "</td>";
        tbl1 += "</tr>";
    }
    let tbl2 = "";
    for (let i = 1; i <= dts_Confrm.getRowCount(); i++) {
        tbl2 += "<tr>";
        tbl2 += "		<td>" + dts_Confrm.getCellData(i, "DUTY_CONFRM_ITM_NM1") + "</td>";
        tbl2 += "		<td>" + (dts_Confrm.getCellData(i, "DUTY_CONFRM_YN1") === 'Y' ? '예' : '아니오') + "</td>";
        tbl2 += "		<td>" + dts_Confrm.getCellData(i, "DUTY_CONFRM_ITM_NM2") + "</td>";
        tbl2 += "		<td>" + (dts_Confrm.getCellData(i, "DUTY_CONFRM_YN2") === 'Y' ? '예' : '') + "</td>";
        tbl2 += "</tr>";
    }
    const userParam = [{
        uid: "CONFRM_DD",
        unm: confrm_dd
    }, {
        uid: "MSG1",
        unm: dts_Procs.getCellData(1, "MSG1")
    }, {
        uid: "MSG2",
        unm: dts_Procs.getCellData(1, "MSG2")
    }, {
        uid: "MSG3",
        unm: dts_Procs.getCellData(1, "MSG4")
    }, {
        uid: "TBL1",
        unm: tbl1
    }, {
        uid: "TBL2",
        unm: tbl2
    }, {
        uid: "print_time",
        unm: ''
    }];
    $c.rpt.fn_open_report_pdf(pdf_rptname, userParam);
    $c.stf.doLogSave('ULDSTF41010.xml', SCREN_PROCS_TP_CD_05);
};

/**
 * @method
 * @name comGridPosEx
 * @description com Grid Pos Ex 처리
 * @param {*} grdObj grdObj
 * @param {*} grdObj2 grdObj2
 * @returns {void}
 * @hidden N
 */
scwin.comGridPosEx = function(grdObj, grdObj2) {
    js_com_Isurcd = grdObj; // 발행사코드
    js_com_Isurnm = grdObj2; // 발행사명
    scwin.IsurTagetPos_ex(grdObj, grdObj2, 'G');
    Grd_com_isur.style.left = js_com_left;
    Grd_com_isur.style.top = js_com_top;
};

/**
 * @method
 * @name IsurTagetPos_ex
 * @description Isur Taget Pos ex 처리
 * @param {*} grdObj grdObj
 * @param {*} grdObj2 grdObj2
 * @param {*} Tg Tg
 * @returns {void}
 * @hidden N
 */
scwin.IsurTagetPos_ex = function(grdObj, grdObj2, Tg) {
    let cL = 7;
    let cT = 53;
    if (Tg === "G") {
        cL = 49;
        cT = 0;
    }
    js_com_left = grdObj.style.left;
    js_com_left = js_com_left.substring(0, js_com_left.length - 2);
    js_com_left = Number(js_com_left) + cL;
    js_com_top = grdObj.style.top;
    js_com_top = js_com_top.substring(0, js_com_top.length - 2);
    js_com_top = Number(js_com_top) + cT;
};

/**
 * @method
 * @name alert_error2
 * @description alert error2 처리
 * @param {*} dtsObj dtsObj
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.alert_error2 = async function(dtsObj) {
    const USER_DEFINE = new Array("INTERNAL", "UNDEFINED", "APP_COMPONENT", "BIZ_COMPONENT", "ACTION", "CORE_FRAMEWORK", "WEB_FRAMEWORK", "INFO");
    for (let i = 0; i < USER_DEFINE.length; i++) {
        const errorCount = dtsObj.SrvErrCount(USER_DEFINE[i]);
        let j;
        for (j = 0; j < errorCount; j++) {
            if (dtsObj.SrvErrCode(USER_DEFINE[i], j) === '0') {
                // '0' 임의로 떨군 INFO 메시지
                await $c.win.alert(dtsObj.SrvErrMsg(USER_DEFINE[i], j));
            } else {
                // 기존 에러 메시지
                await $c.win.alert("[CODE: " + dtsObj.SrvErrCode(USER_DEFINE[i], j) + "] " + dtsObj.SrvErrMsg(USER_DEFINE[i], j));
            }
        }
    }
};
